/**
 * Get a random array from a range.
 *
 * @param {number} min
 * @param {number} max
 * @param {number} [n=1]
 * @returns {number[]}
 */
const randomIntArrayInRange = (min, max, n = 1) => Array.from({ length: n }, () => Math.floor(Math.random() * (max - min + 1)) + min);
export default randomIntArrayInRange;
